// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number,
        uint64 _timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {

        vm.prank(DEPOSITOR);
        c.setL1BlockValues(
            number,
            _timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        );

        assertTrue(c.timestamp() == _timestamp);
    }
}
